<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#111}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #ddd;padding:8px;text-align:left}</style></head><body><h1>Fuel Station Report</h1><p>Period: {{ $from->format('Y-m-d') }} to {{ $to->format('Y-m-d') }}</p><h2>Revenue: RWF {{ number_format($revenue, 2) }}</h2><table><thead><tr><th>Date</th><th>Customer</th><th>Payment</th><th>Total</th></tr></thead><tbody>@foreach($sales as $sale)<tr><td>{{ $sale->sale_date->format('Y-m-d') }}</td><td>{{ $sale->customer?->name ?? 'Walk-in customer' }}</td><td>{{ $sale->payment_method }}</td><td>{{ $sale->total_amount }}</td></tr>@endforeach</tbody></table><h2>Fuel Stock</h2><table><tbody>@foreach($stock as $fuel)<tr><td>{{ $fuel->fuel_name }}</td><td>{{ $fuel->available_quantity }} L</td><td>RWF {{ $fuel->price_per_liter }}</td></tr>@endforeach</tbody></table></body></html>
